func (a AuthenticationMethodGithubConfig) validate() error {
	if err := validateOAuthProviderCredentials("github", a.ClientId, a.ClientSecret, a.RedirectAddress); err != nil {
		return err
	}

	// ensure scopes contain read:org if allowed organizations is not empty
	if len(a.AllowedOrganizations) > 0 && !slices.Contains(a.Scopes, "read:org") {
		return fmt.Errorf("provider %q: field %q: must contain read:org when allowed_organizations is not empty", "github", "scopes")
	}

	return nil
}

func validateOAuthProviderCredentials(provider, clientID, clientSecret, redirectAddress string) error {
	for _, field := range []struct {
		name  string
		value string
	}{
		{"client_id", clientID},
		{"client_secret", clientSecret},
		{"redirect_address", redirectAddress},
	} {
		if strings.TrimSpace(field.value) == "" {
			return fmt.Errorf("provider %q: %w", provider, errFieldRequired(field.name))
		}
	}

	return nil
}
